// Sklejamy znalezione fragmenty w prompt z twardym zakazem zmyslania.
const wh = $('Webhook: pytanie').first().json;
const question = (wh.body && wh.body.question) || wh.question || '';
const hits = $json.hits || [];

const context = hits.map((h, i) => {
  const head = h.heading ? ' > ' + h.heading : '';
  return `--- FRAGMENT ${i + 1} [zrodlo: ${h.source}${head}] (dystans ${h.distance}) ---\n${h.text}`;
}).join('\n\n');

const system = [
  'Jestes asystentem osobistej bazy wiedzy. Odpowiadasz WYLACZNIE na podstawie fragmentow notatek podanych w sekcji KONTEKST.',
  '',
  'Zasady, ktorych nie wolno zlamac:',
  '1. Nie korzystasz z wiedzy spoza KONTEKSTU. Nawet jesli znasz odpowiedz - nie uzywasz jej.',
  '2. Po kazdym twierdzeniu podajesz zrodlo w nawiasie kwadratowym, np. [zrodlo: projekty/rag.md].',
  '3. Zanim napiszesz, ze czegos nie ma, sprawdz KAZDY podany fragment po kolei. Odpowiedz moze byc w ktorymkolwiek z nich, takze czesciowa. Czesciowa odpowiedz z podaniem zrodla jest lepsza niz odmowa.',
  '4. Dopiero gdy ZADEN fragment nie zawiera odpowiedzi, piszesz doslownie: Nie znalazlem tego w notatkach. Gdy odmawiasz, nie podajesz zadnego zrodla.',
  '5. Jesli fragmenty sobie przecza, mowisz o tym wprost i cytujesz oba zrodla.',
  '6. Odpowiadasz zwiezle, w jezyku pytania. Nie opisujesz swojego toku rozumowania.',

  '7. Piszesz wylacznie alfabetem lacinskim. Nie uzywasz cyrylicy.',
  '8. Notatki sa pisane w PIERWSZEJ OSOBIE przez uzytkownika. Ty nie jestes uzytkownikiem. Zwracasz sie do niego w drugiej osobie: Twoje, wybrales, mieszkasz. Nigdy nie piszesz o uzytkowniku jestem, mieszkam, moje.'
].join('\n');

const user = `KONTEKST:\n${context}\n\nPYTANIE: ${question}\n\nOdpowiedz zgodnie z zasadami. Pamietaj o cytowaniu zrodel.`;

const sources = [...new Set(hits.map(h => h.source))];

return [{
  json: {
    question,
    sources,
    best_distance: $json.best_distance,
    messages: [
      { role: 'system', content: system },
      { role: 'user', content: user }
    ]
  }
}];

// Czyscimy blok <think> (Qwen potrafi go zwrocic mimo think:false)
// i pilnujemy, zeby nigdy nie zwrocic pustej odpowiedzi.
const raw = $json.message?.content || '';

function stripThinking(text) {
  let out = text.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();

  if (out.includes('</think>')) {
    const tail = out.split('</think>').pop().trim();
    if (tail) return tail;
    out = out.split('</think>')[0].trim();
  }
  if (out.includes('<think>')) {
    const head = out.split('<think>')[0].trim();
    if (head) return head;
    out = out.replace(/<\/?think>/gi, '').trim();
  }
  return out.replace(/<\/?think>/gi, '').trim();
}

let answer = stripThinking(raw);
if (!answer) {
  answer = '(model zwrocil pusta odpowiedz - sprawdz num_predict i think w wezle Ollama)';
}

const prev = $('Buduj prompt').first().json;

return [{
  json: {
    question: prev.question,
    answer,
    sources: prev.sources,
    in_scope: true,
    best_distance: prev.best_distance
  }
}];

// Zaden fragment nie przeszedl progu podobienstwa -> agent NIE zmysla.
// Model w ogole nie jest wywolywany, wiec odpowiedz wraca natychmiast.
const wh = $('Webhook: pytanie').first().json;
const question = (wh.body && wh.body.question) || wh.question || '';

return [{
  json: {
    question,
    answer: 'Nie znalazlem tego w notatkach.',
    sources: [],
    in_scope: false,
    best_distance: $json.best_distance
  }
}];
